template:
module top_module(input a, b, output out);
  // assign out = a & b;
endmodule

testbench:
`timescale 1ns/1ps
module tb;
  reg a,b; wire out;
  top_module dut(a,b,out);
  initial begin
    $display("Testing AND gate...");
    a=0;b=0;#10; if(out!==1'b0) $display("FAIL: 0&0=0, got %b", out);
    a=0;b=1;#10; if(out!==1'b0) $display("FAIL: 0&1=0, got %b", out);
    a=1;b=0;#10; if(out!==1'b0) $display("FAIL: 1&0=0, got %b", out);
    a=1;b=1;#10; if(out!==1'b1) $display("FAIL: 1&1=1, got %b", out);
    $display("✅ PASS: All tests correct!");
    $finish;
  end
endmodule

