template:
module top_module(input a, b, cin, output Sum, Cout);
  // assign Sum = a ^ b ^ cin;
  // assign Cout = (a & b) | (b & cin) | (a & cin);
endmodule

testbench:
`timescale 1ns/1ps
module tb;
  reg a,b,cin; wire Sum,Cout;
  top_module dut(a,b,cin,Sum,Cout);
  initial begin
    $display("Testing Full Adder...");
    // Test all 8 combinations
    a=0;b=0;cin=0;#10; if({Cout,Sum}!==2'b00) $display("FAIL: 0+0+0=00, got %b%b", Cout,Sum);
    a=0;b=0;cin=1;#10; if({Cout,Sum}!==2'b01) $display("FAIL: 0+0+1=01, got %b%b", Cout,Sum);
    a=0;b=1;cin=0;#10; if({Cout,Sum}!==2'b01) $display("FAIL: 0+1+0=01, got %b%b", Cout,Sum);
    a=0;b=1;cin=1;#10; if({Cout,Sum}!==2'b10) $display("FAIL: 0+1+1=10, got %b%b", Cout,Sum);
    a=1;b=0;cin=0;#10; if({Cout,Sum}!==2'b01) $display("FAIL: 1+0+0=01, got %b%b", Cout,Sum);
    a=1;b=0;cin=1;#10; if({Cout,Sum}!==2'b10) $display("FAIL: 1+0+1=10, got %b%b", Cout,Sum);
    a=1;b=1;cin=0;#10; if({Cout,Sum}!==2'b10) $display("FAIL: 1+1+0=10, got %b%b", Cout,Sum);
    a=1;b=1;cin=1;#10; if({Cout,Sum}!==2'b11) $display("FAIL: 1+1+1=11, got %b%b", Cout,Sum);
    $display("✅ PASS: All 8 test cases correct!");
    $finish;
  end
endmodule

template:
module top_module(input clk, input d, output reg q);
  // always @(posedge clk) q <= d;
endmodule

testbench:
`timescale 1ns/1ps
module tb;
  reg clk=0,d; wire q;
  top_module dut(clk,d,q);
  always #5 clk=~clk;
  initial begin
    $display("Testing D Flip-Flop...");
    d=0; #10; if(q!==1'b0) $display("FAIL: After 1st posedge, q should be 0");
    d=1; #10; if(q!==1'b1) $display("FAIL: After 2nd posedge, q should be 1");
    d=0; #10; if(q!==1'b0) $display("FAIL: After 3rd posedge, q should be 0");
    d=1; #10; if(q!==1'b1) $display("FAIL: After 4th posedge, q should be 1");
    $display("✅ PASS: D Flip-Flop works correctly!");
    $finish;
  end
endmodule
